import{_ as e}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as a,o as d,af as n}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const b=JSON.parse('{"title":"CodeBuddy Learning Map","description":"Tencent Cloud CodeBuddy is a family of AI coding surfaces that share one account quota: a standalone IDE, editor plugins, and a terminal CLI. This page is the family map and decision tree.","frontmatter":{"title":"CodeBuddy Learning Map","description":"Tencent Cloud CodeBuddy is a family of AI coding surfaces that share one account quota: a standalone IDE, editor plugins, and a terminal CLI. This page is the family map and decision tree.","domain":"product","tags":["coding-agent"],"role":"map"},"headers":[],"relativePath":"products/codebuddy/index.md","filePath":"products/codebuddy/index.md","lastUpdated":1787110548000}'),r={name:"products/codebuddy/index.md"};function o(s,t,i,l,c,h){return d(),a("div",null,[...t[0]||(t[0]=[n(`<h1 id="codebuddy-learning-map" tabindex="-1">CodeBuddy Learning Map <a class="header-anchor" href="#codebuddy-learning-map" aria-label="Permalink to &quot;CodeBuddy Learning Map&quot;">​</a></h1><blockquote><p>Tencent Cloud Code Assistant <strong>CodeBuddy</strong> ships <strong>IDE, plugin, and CLI</strong> forms. Official wording (<a href="https://www.codebuddy.cn/docs/" target="_blank" rel="noreferrer">docs overview</a>, <a href="https://cloud.tencent.com/document/product/1831/134343" target="_blank" rel="noreferrer">Tencent Cloud product overview</a>):</p><p>The product supports IDE, plugin, and CLI forms, covering full-scenario needs from professional developers to zero-foundation users.</p></blockquote><p>This page is the landscape and decision tree — <strong>name the surface first, then decide what to learn</strong>. Install steps live in the <a href="./codebuddy.html">tutorial</a>.</p><h2 id="product-family" tabindex="-1">Product family <a class="header-anchor" href="#product-family" aria-label="Permalink to &quot;Product family&quot;">​</a></h2><p>Top-level entries on the docs site (opened 2026-08-18 at <a href="https://www.codebuddy.cn/docs/" target="_blank" rel="noreferrer">codebuddy.cn/docs</a>):</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Tencent Cloud / CodeBuddy family</span></span>
<span class="line"><span>├── CodeBuddy IDE — standalone editor, &quot;conversation is programming&quot;</span></span>
<span class="line"><span>├── CodeBuddy Plugin — extension inside VS Code / JetBrains / …</span></span>
<span class="line"><span>├── CodeBuddy Code (CLI) — terminal agent, command \`codebuddy\`</span></span>
<span class="line"><span>├── WorkBuddy — office workbench (no tutorial in this directory)</span></span>
<span class="line"><span>│   ├── WorkBuddy mini program</span></span>
<span class="line"><span>│   └── WorkBuddy mobile</span></span>
<span class="line"><span>└── Enterprise — SaaS flagship / dedicated edition (no tutorial here)</span></span>
<span class="line"><span>Same-vendor AI (no tutorial in this directory)</span></span>
<span class="line"><span>├── Yuanbao — general assistant</span></span>
<span class="line"><span>└── Hunyuan — model, not a coding product</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Official first-level entry</th><th>What it is</th><th>Official URL</th><th>This site</th></tr></thead><tbody><tr><td><strong>CodeBuddy IDE</strong></td><td>Product-design-dev workbench; &quot;conversation is programming&quot;</td><td><a href="https://www.codebuddy.cn/docs/" target="_blank" rel="noreferrer">Docs overview</a> · <a href="https://www.codebuddy.cn/docs/ide/Getting-Started/Installation" target="_blank" rel="noreferrer">Install</a> · <a href="https://www.codebuddy.cn/ide/" target="_blank" rel="noreferrer">Download</a></td><td><a href="./codebuddy.html#install-the-ide">Tutorial</a></td></tr><tr><td><strong>CodeBuddy Plugin</strong></td><td>AI assist inside an existing editor</td><td><a href="https://www.codebuddy.cn/docs/plugin/" target="_blank" rel="noreferrer">Plugin docs</a></td><td><a href="./codebuddy.html#install-the-plugin">Tutorial</a></td></tr><tr><td><strong>CodeBuddy Code (CLI)</strong></td><td>Natural-language driven development in the terminal</td><td><a href="https://www.codebuddy.cn/docs/cli/" target="_blank" rel="noreferrer">CLI docs</a> · <a href="https://www.codebuddy.cn/docs/cli/installation" target="_blank" rel="noreferrer">Install</a></td><td><a href="./codebuddy.html#install-the-cli">Tutorial</a></td></tr><tr><td><strong>WorkBuddy</strong></td><td>&quot;Tencent&#39;s all-scenario AI office workbench.&quot;</td><td><a href="https://www.codebuddy.cn/docs/workbuddy/" target="_blank" rel="noreferrer">WorkBuddy intro</a> · <a href="https://www.codebuddy.cn/work/" target="_blank" rel="noreferrer">Site /work</a></td><td><strong>One map row</strong>, no tutorial</td></tr><tr><td><strong>WorkBuddy mini program</strong></td><td>One mobile entry for WorkBuddy</td><td><a href="https://www.codebuddy.cn/docs/workbuddymini/" target="_blank" rel="noreferrer">Mini program intro</a></td><td><strong>One map row</strong>, no tutorial</td></tr><tr><td><strong>WorkBuddy mobile</strong></td><td>Companion app for desktop WorkBuddy</td><td><a href="https://www.codebuddy.cn/docs/workbuddyapp/" target="_blank" rel="noreferrer">Mobile intro</a></td><td><strong>One map row</strong>, no tutorial</td></tr><tr><td><strong>Enterprise</strong></td><td>SaaS flagship / dedicated private-cloud edition</td><td><a href="https://www.codebuddy.cn/docs/ide/Codebuddy-enterprise-edition/Codebuddy-enterprise-purchase" target="_blank" rel="noreferrer">Purchase flow</a> · <a href="https://cloud.tencent.com/document/product/1831/134343" target="_blank" rel="noreferrer">Cloud overview</a></td><td><strong>One map row</strong>, no tutorial</td></tr><tr><td><strong>Yuanbao</strong></td><td>Tencent general AI assistant</td><td><a href="https://yuanbao.tencent.com/" target="_blank" rel="noreferrer">yuanbao.tencent.com</a></td><td><strong>One map row</strong> (issue #76)</td></tr><tr><td><strong>Hunyuan</strong></td><td>Tencent model; one of the engines CodeBuddy can switch to</td><td><a href="https://hunyuan.tencent.com/" target="_blank" rel="noreferrer">hunyuan.tencent.com</a> · <a href="https://cloud.tencent.com/product/tclm" target="_blank" rel="noreferrer">Cloud tclm</a></td><td><strong>One map row</strong> (issue #77)</td></tr></tbody></table><p><strong>Out of scope</strong>: WeChat, QQ, CVM, payments. If those appear in a vendor nav, mark them &quot;not this site&quot;.</p><p>Official form comparison (<a href="https://cloud.tencent.com/document/product/1831/134343" target="_blank" rel="noreferrer">product overview</a>):</p><table tabindex="0"><thead><tr><th></th><th><strong>CodeBuddy Plugin</strong></th><th><strong>CodeBuddy IDE</strong></th><th><strong>CodeBuddy Code</strong></th></tr></thead><tbody><tr><td>Audience</td><td>Everyday coders / people locked to one IDE</td><td>PMs / designers / full-stack / beginners</td><td>DevOps / SRE / senior engineers</td></tr><tr><td>Strength</td><td>Plug in, stay in the current workflow</td><td>Product-design-dev; CloudBase / EdgeOne Pages / CloudStudio</td><td>Shell / files / network; headless; task orchestration / Sub Agent</td></tr><tr><td>How to start</td><td>Search <strong>腾讯云代码助手</strong> in the marketplace</td><td>Intl <a href="https://www.codebuddy.ai/" target="_blank" rel="noreferrer">codebuddy.ai</a> · CN <a href="https://copilot.tencent.com/ide" target="_blank" rel="noreferrer">copilot.tencent.com/ide</a></td><td><code>npm install -g @tencent-ai/codebuddy-code</code></td></tr></tbody></table><p>The three coding forms <strong>share one account quota</strong> (<a href="https://www.codebuddy.cn/docs/cli/troubleshooting" target="_blank" rel="noreferrer">troubleshooting</a>).</p><h3 id="quick-decision-which-surface" tabindex="-1">Quick decision: which surface? <a class="header-anchor" href="#quick-decision-which-surface" aria-label="Permalink to &quot;Quick decision: which surface?&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>What am I doing?</span></span>
<span class="line"><span>├── I already live in VS Code / JetBrains / Visual Studio</span></span>
<span class="line"><span>│   └── → Plugin (marketplace search 腾讯云代码助手)</span></span>
<span class="line"><span>├── I want one sentence → prototype / mock / deployable app</span></span>
<span class="line"><span>│   └── → IDE</span></span>
<span class="line"><span>├── The work is in a terminal: scripts, CI, bulk refactors, headless</span></span>
<span class="line"><span>│   └── → CodeBuddy Code (\`codebuddy\` / \`codebuddy -p\`)</span></span>
<span class="line"><span>├── Office docs / PPT / local file batching, not a git repo</span></span>
<span class="line"><span>│   └── → WorkBuddy (not taught here)</span></span>
<span class="line"><span>└── General chat / search, not a coding product</span></span>
<span class="line"><span>    └── → Yuanbao (not taught here)</span></span></code></pre></div><p>Three name collisions to lock in:</p><table tabindex="0"><thead><tr><th>Easy to confuse</th><th>Difference</th></tr></thead><tbody><tr><td><strong>CodeBuddy</strong> vs <strong>WorkBuddy</strong></td><td>Coding family vs office workbench</td></tr><tr><td><strong>Editor plugin</strong> vs <strong>CLI <code>plugin</code></strong></td><td>VS Code extension vs <code>codebuddy plugin install</code></td></tr><tr><td><strong>Hunyuan</strong> vs <strong>CodeBuddy</strong></td><td>Model vs product; official docs also mention DeepSeek</td></tr></tbody></table><p>More look-alikes live in the <a href="./codebuddy-glossary.html">Glossary</a>.</p><h2 id="which-page-to-read" tabindex="-1">Which page to read <a class="header-anchor" href="#which-page-to-read" aria-label="Permalink to &quot;Which page to read&quot;">​</a></h2><p>This set follows <a href="https://diataxis.fr/" target="_blank" rel="noreferrer">Diataxis</a>:</p><table tabindex="0"><thead><tr><th>Page</th><th>Type</th><th>When</th></tr></thead><tbody><tr><td><a href="./codebuddy.html">Tutorial</a></td><td>Tutorial</td><td>First time: install IDE / plugin / CLI → sign in → first chat</td></tr><tr><td><a href="./codebuddy-cookbook.html">Cookbook</a></td><td>How-to</td><td>Already running; copy <code>/init</code>, print mode, custom commands, MCP, migration</td></tr><tr><td><a href="./codebuddy-cheatsheet.html">Cheatsheet</a></td><td>Reference</td><td>Install text, CLI commands, slash commands, keys</td></tr><tr><td><a href="./codebuddy-glossary.html">Glossary</a></td><td>Explanation</td><td>Forms, permission modes, <code>CODEBUDDY.md</code>, CN vs intl sites</td></tr></tbody></table><h2 id="learning-path" tabindex="-1">Learning path <a class="header-anchor" href="#learning-path" aria-label="Permalink to &quot;Learning path&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Stage</th><th>Read</th><th>Goal</th></tr></thead><tbody><tr><td>1. Pick a form and install it</td><td><a href="./codebuddy.html">Tutorial</a></td><td>Sign in on one surface in 15 minutes</td></tr><tr><td>2. First real task</td><td>Tutorial first chat; CLI starts with <code>/init</code></td><td>Let it read the repo or make a small edit</td></tr><tr><td>3. Daily workflow</td><td><a href="./codebuddy-cookbook.html">Cookbook</a></td><td>Print mode, slash commands, MCP</td></tr><tr><td>4. Look up flags</td><td><a href="./codebuddy-cheatsheet.html">Cheatsheet</a></td><td>Commands and official install text</td></tr><tr><td>5. Untangle names</td><td><a href="./codebuddy-glossary.html">Glossary</a></td><td>WorkBuddy / Hunyuan / CLI plugin stay distinct</td></tr></tbody></table><h2 id="feature-snapshot" tabindex="-1">Feature snapshot <a class="header-anchor" href="#feature-snapshot" aria-label="Permalink to &quot;Feature snapshot&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Capability</th><th>Where</th><th>Official source</th></tr></thead><tbody><tr><td>Inline completion, chat, <code>@workspace</code> / <code>#Codebase</code></td><td>Plugin</td><td><a href="https://cloud.tencent.com/document/product/1831/134343" target="_blank" rel="noreferrer">Product overview</a></td></tr><tr><td>Natural language → PRD / design / code / one-click deploy</td><td>IDE</td><td>Same</td></tr><tr><td>Interactive REPL, <code>codebuddy -p</code>, slash commands, MCP</td><td>CLI</td><td><a href="https://www.codebuddy.cn/docs/cli/quickstart" target="_blank" rel="noreferrer">Quick start</a> · <a href="https://www.codebuddy.cn/docs/cli/cli-reference" target="_blank" rel="noreferrer">CLI reference</a></td></tr><tr><td>Skills / Hooks / subagents / Daemon</td><td>CLI (advanced)</td><td><a href="https://www.codebuddy.cn/docs/cli/" target="_blank" rel="noreferrer">CLI tree</a></td></tr></tbody></table><h2 id="goals-and-non-goals" tabindex="-1">Goals and non-goals <a class="header-anchor" href="#goals-and-non-goals" aria-label="Permalink to &quot;Goals and non-goals&quot;">​</a></h2><p><strong>Goal</strong>: Help a front-end engineer tell the three CodeBuddy coding surfaces apart, then install, sign in, and finish a first task from official steps.</p><p><strong>Non-goals</strong>:</p><ul><li>No full tutorials for Yuanbao, Hunyuan, or WorkBuddy</li><li>No WeChat / QQ product pages</li><li>No model internals</li><li>No recycling of marketing percentages as measured results</li></ul><h2 id="resources" tabindex="-1">Resources <a class="header-anchor" href="#resources" aria-label="Permalink to &quot;Resources&quot;">​</a></h2><ul><li><a href="https://www.codebuddy.cn/docs/" target="_blank" rel="noreferrer">CN docs</a></li><li><a href="https://www.codebuddy.ai/docs/" target="_blank" rel="noreferrer">Intl docs</a> · <a href="https://www.codebuddy.ai/docs/zh/" target="_blank" rel="noreferrer">ZH mirror</a></li><li><a href="https://cloud.tencent.com/product/acc" target="_blank" rel="noreferrer">Tencent Cloud product acc</a></li><li><a href="https://www.codebuddy.cn/pricing/" target="_blank" rel="noreferrer">Pricing</a> — client-rendered; do not invent plan numbers here</li><li><a href="./codebuddy-cheatsheet.html#high-quality-sources">Cheatsheet · sources</a></li></ul>`,29)])])}const m=e(r,[["render",o]]);export{b as __pageData,m as default};
